                    case BOP_SUB: aop = IR_SUB; break;
                    case BOP_MUL: aop = IR_MUL; break;
                    case BOP_DIV: aop = IR_DIV; break;
                    case BOP_MOD: aop = IR_MOD; break;
                    case BOP_BITAND: case BOP_AND: aop = IR_BAND; break;
