    VaArgPackFrame *fr = &g_vapack_stack[g_vapack_depth++];
    runtime.memset(fr, 0, sizeof(*fr));
    fr->extra = extra;
    fr->extra_len = extra_len;
    fr->join_label = new_label(fn);
    fr->ret_type = callee->ret_type;
    fr->is_void = (callee->ret_type.kind == TY_VOID);
    fr->result_slot = -1;
